// WF2b "Plan signals": compute FREE signals from data already collected and pick leads that need
// the paid review scrape (capped by the credits still reserved on the job).
//
// Normalized value convention: value in 0..1 where 1 = the signal's "high" state
//   has_website : 1 = has a website, 0 = none
//   size_proxy  : 0.60 * reviews (log scale, ~2000 reviews = 1) + 0.15 * rating above 3 + 0.25 * extra branches (3+ = 1)
const body = $('Webhook').first().json.body;
const job = $('Get job').first().json;
const campaign = $('Get campaign').first().json;
const perLeadRes = $('Reviews cost').first().json;
const perLead = Number(perLeadRes !== null && typeof perLeadRes === 'object' ? (perLeadRes.data ?? Object.values(perLeadRes)[0]) : perLeadRes) || 0;

const campaignSignals = ((campaign.parameters || {}).signals || []).filter((s) => s && Number(s.weight) !== 0);
const on = new Set(campaignSignals.map((s) => s.key));
const wantsInsights = on.has('review_insights');
const wantsAge = on.has('business_age');

const links = $('Get campaign leads').all().map((i) => i.json).filter((r) => r.leads);
const fresh = new Set($('Get fresh signals').all().map((i) => `${i.json.lead_id}|${i.json.signal_key}`));

const baseName = (n) => String(n || '').split(/\s[-–|]\s|\(|\|/)[0].toLowerCase().replace(/[^\p{L}\p{N}]+/g, ' ').trim();
const branchCount = new Map();
for (const r of $('Get org names').all()) {
  const k = baseName(r.json.business_name);
  if (k) branchCount.set(k, (branchCount.get(k) || 0) + 1);
}

const now = new Date().toISOString();
const mk = (lead_id, signal_key, value, raw) => ({
  organization_id: body.organization_id,
  lead_id,
  signal_key,
  raw,
  normalized: { value: Math.max(0, Math.min(1, Math.round(value * 1000) / 1000)) },
  source: signal_key === 'has_website' || signal_key === 'size_proxy' ? 'google_maps_data' : 'compass/google-maps-reviews-scraper',
  job_id: body.job_id,
  collected_at: now,
});

const freeRows = [];
for (const r of links) {
  const l = r.leads;
  if (on.has('has_website')) freeRows.push(mk(l.id, 'has_website', l.website ? 1 : 0, { has_website: !!l.website }));
  if (on.has('size_proxy')) {
    const reviews = Number(l.reviews_count) || 0;
    const rating = Number(l.rating) || 0;
    const branches = Math.max(1, branchCount.get(baseName(l.business_name)) || 1);
    const rc = Math.min(1, Math.log10(1 + reviews) / 3.3);
    const rt = Math.max(0, Math.min(1, (rating - 3) / 2));
    const bc = Math.min(1, (branches - 1) / 3);
    freeRows.push(mk(l.id, 'size_proxy', 0.6 * rc + 0.15 * rt + 0.25 * bc, { reviews_count: reviews, rating, branches }));
  }
}

let targets = [];
if ((wantsInsights || wantsAge) && perLead > 0) {
  const stillFresh = (id) => (!wantsInsights || fresh.has(`${id}|review_insights`)) && (!wantsAge || fresh.has(`${id}|business_age`));
  const all = links.map((r) => r.leads).filter((l) => l.google_place_id && !stillFresh(l.id));
  const spent = Number((job.counts || {}).new) || 0;
  const affordable = Math.max(0, Math.floor((job.credits_reserved - spent) / perLead));
  targets = all.slice(0, affordable).map((l) => ({ lead_id: l.id, place_id: l.google_place_id, business_name: l.business_name, reviews_count: l.reviews_count }));
}

const reviewsRequest = {
  placeIds: targets.map((t) => t.place_id),
  maxReviews: 10,
  reviewsSort: 'newest',
  language: 'ar',
  personalData: false,
};

return [{
  json: {
    freeRows,
    targets,
    perLead,
    wantsInsights,
    wantsAge,
    hasTargets: targets.length > 0,
    reviewsRequestBody: JSON.stringify(reviewsRequest),
  },
}];

// WF2b "Group reviews": one item per lead that actually has reviews, with the business_age row
// and (when there is enough review text) an OpenRouter request for review_insights.
//
// business_age convention: value 1 = looks NEW, 0 = established.
// Only the 10 newest reviews are fetched, so true age is ESTIMATED from review velocity:
//   spanMonths = months covered by the visible reviews; velocity = visible / spanMonths
//   estAgeMonths = reviews_count / velocity (if the visible window already holds every review, the real oldest date is used)
//   value = 1 - clamp((estAgeMonths - 6) / (30 - 6), 0, 1)
const body = $('Webhook').first().json.body;
const plan = $('Plan signals').first().json;
const res = $input.first().json || {};
const now = Date.now();
const MONTH = 30.44 * 24 * 3600 * 1000;

const ok = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300 && Array.isArray(res.body);
if (!ok) return [{ json: { empty: true, error: String(res.statusCode || (res.error && (res.error.message || res.error)) || 'unknown') } }];

const byPlace = new Map();
for (const r of res.body) {
  if (!r || !r.placeId) continue;
  if (!byPlace.has(r.placeId)) byPlace.set(r.placeId, []);
  byPlace.get(r.placeId).push(r);
}

const SYSTEM = `You summarize Google Maps reviews of a business. Return ONE JSON object only:
{"summary_ar": string (max 160 chars, Egyptian colloquial Arabic), "praise": [string] (max 3, short Arabic), "complaints": [string] (max 3, short Arabic), "complaint_level": number 0..1 (0 = no complaints, 1 = mostly complaints), "top_complaint_ar": string|null (the single most repeated complaint as a short Arabic noun phrase of up to 4 words, or null if none)}.
Use ONLY what the reviews say. Do not invent anything.`;

const items = [];
for (const t of plan.targets) {
  const rev = byPlace.get(t.place_id);
  if (!rev || !rev.length) continue;
  const dates = rev.map((r) => Date.parse(r.publishedAtDate)).filter(Number.isFinite).sort((a, b) => a - b);
  const texts = rev.map((r) => ({ stars: r.stars ?? null, text: (r.text || r.textTranslated || '').toString().slice(0, 400) })).filter((r) => r.text.trim());

  let ageRow = null;
  if (plan.wantsAge && dates.length) {
    const spanMonths = Math.max(0.25, (now - dates[0]) / MONTH);
    const total = Number(t.reviews_count) || rev.length;
    const complete = total <= rev.length;
    const est = complete ? spanMonths : total / (rev.length / spanMonths);
    const value = 1 - Math.max(0, Math.min(1, (est - 6) / 24));
    ageRow = {
      organization_id: body.organization_id,
      lead_id: t.lead_id,
      signal_key: 'business_age',
      raw: { visible_reviews: rev.length, oldest_visible: new Date(dates[0]).toISOString(), newest_visible: new Date(dates[dates.length - 1]).toISOString(), est_age_months: Math.round(est * 10) / 10, method: complete ? 'oldest_review' : 'velocity_estimate' },
      normalized: { value: Math.round(value * 1000) / 1000 },
      source: 'compass/google-maps-reviews-scraper',
      job_id: body.job_id,
      collected_at: new Date().toISOString(),
    };
  }

  let llm = false;
  let requestBody = '{}';
  if (plan.wantsInsights && texts.length >= 3) {
    llm = true;
    const req = {
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: JSON.stringify({ business: t.business_name, reviews: texts }) },
      ],
      response_format: { type: 'json_object' },
      temperature: 0.2,
      usage: { include: true },
    };
    const fb = Array.isArray(body.fallback_models) ? body.fallback_models.filter(Boolean) : [];
    if (fb.length) req.models = [body.model, ...fb]; else req.model = body.model;
    requestBody = JSON.stringify(req);
  }
  items.push({ json: { lead_id: t.lead_id, place_id: t.place_id, n_reviews: rev.length, n_texts: texts.length, ageRow, llm, requestBody } });
}
if (!items.length) return [{ json: { empty: true, error: 'no_reviews' } }];
return items;

// WF2b "Parse signals": collect business_age rows and review_insights rows (LLM) for the paid signals.
const body = $('Webhook').first().json.body;
const groups = $('Group reviews').all().map((i) => i.json);
let llmOut = [];
try { llmOut = $('OpenRouter insights').all(); } catch (e) { llmOut = []; }
const llmGroups = groups.filter((g) => g.llm);

const rows = [];
const usage = { in: 0, out: 0, cost: 0, model: null };
const clamp01 = (v) => Math.max(0, Math.min(1, Number(v) || 0));

groups.forEach((g) => { if (g.ageRow) rows.push(g.ageRow); });

llmGroups.forEach((g, j) => {
  const r = (llmOut[j] || {}).json || {};
  const u = (r.body && r.body.usage) || {};
  usage.in += u.prompt_tokens || 0;
  usage.out += u.completion_tokens || 0;
  usage.cost += Number(u.cost) || 0;
  usage.model = (r.body && r.body.model) || usage.model;
  if (!(r.statusCode >= 200 && r.statusCode < 300) || !r.body || !r.body.choices) return;
  let d;
  try { d = JSON.parse((r.body.choices[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { return; }
  const top = typeof d.top_complaint_ar === 'string' && d.top_complaint_ar.trim() ? d.top_complaint_ar.trim().slice(0, 40) : null;
  const normalized = { value: Math.round(clamp01(d.complaint_level) * 1000) / 1000 };
  if (top) normalized.label_ar = `الريفيوهات بتشتكي من ${top}`;
  rows.push({
    organization_id: body.organization_id,
    lead_id: g.lead_id,
    signal_key: 'review_insights',
    raw: {
      summary_ar: String(d.summary_ar || '').slice(0, 200),
      praise: Array.isArray(d.praise) ? d.praise.slice(0, 3).map((x) => String(x).slice(0, 60)) : [],
      complaints: Array.isArray(d.complaints) ? d.complaints.slice(0, 3).map((x) => String(x).slice(0, 60)) : [],
      n_reviews: g.n_reviews,
      n_texts: g.n_texts,
    },
    normalized,
    source: 'compass/google-maps-reviews-scraper+llm',
    job_id: body.job_id,
    collected_at: new Date().toISOString(),
  });
});

return [{ json: { rows, chargedLeads: groups.length, usage } }];

// WF2b "Finish": final credit usage and counts for the whole ingest job (leads + signals).
const body = $('Webhook').first().json.body;
const job = $('Get job').first().json;
const plan = $('Plan signals').first().json;
let parsed = null;
try { parsed = $('Parse signals').first().json; } catch (e) { parsed = null; }
let warning = null;
try { const g = $('Group reviews').first().json; if (g && g.empty && g.error) warning = String(g.error); } catch (e) { /* node did not run */ }

const charged = parsed ? parsed.chargedLeads : 0;
const newLeads = Number((job.counts || {}).new) || 0;
const used = newLeads + charged * plan.perLead;

return [{
  json: {
    job_id: body.job_id,
    campaign_id: body.campaign_id,
    credits_used: used,
    counts: {
      ...(job.counts || {}),
      signals_free: plan.freeRows.length,
      review_targets: plan.targets.length,
      reviews_scraped: charged,
      signals_warning: warning,
    },
    usage: parsed ? parsed.usage : { in: 0, out: 0, cost: 0, model: null },
  },
}];
